#!/usr/bin/env python3
"""Design B: a pattern NNUE whose per-location 3^9 pattern table is GENERATED by a small shared
network (nnue2 plan section 3; critique experiment 2). Full replacement: predicts the whole eval,
no HCE underneath.

Per perspective (side to move "us", opponent "them"; patterns written from that side's view,
0 empty / 1 mine / 2 theirs, index sum_i cell_i 3^i exactly as probe.Pat):
  live miniboard m      T[m, pattern_m] = P_m(enc(onehot27(pattern_m))) (A+1 wide)
  decided miniboard m   D[m, mine / theirs / drawn]                       free rows
  constraint c (0..9)   C_us[c] for the side to move, C_them[c] for the other perspective
  forced board (c < 9)  P_f(enc(onehot27(pattern of board c)))           optional
  enc: 27 -> 64 -> 64 -> 32 (ReLU between, linear 32-d embedding), shared across locations;
  P_m, P_f: 32 -> A+1 (A accumulator lanes + 1 PSQT lane).
Clipped ReLU [0,1] on each A-wide accumulator, dense 2A -> 16 -> 32 -> 1 (or 2A -> 32 -> 1),
eval = 1000 * (dense + (psqt_us - psqt_them) / 2); auxiliary loss 0.1 * MSE on the PSQT lane alone.
Data, split, K, target and augmentation are probe.py's (eval2 + first N rows of a depth-8 file,
10% game holdout V2, K 1600, win-probability MSE, random D4 transform per row per step).

Subcommands:
  check                 unit checks: pattern index order / mine-theirs convention against probe.Pat,
                        generated rows against a direct per-cell path, forced boards are live
  bench                 synthetic DirectML throughput for a few arm shapes
  train --run NAME,A,DENSE,LR[,forced=0|1][,sharedcon=0|1][,seed=N][,epochs=N][,aug=0|1][,static=0|1] [--run ...]
                        train arms sequentially on one data load (DENSE like 16x32 or 32);
                        writes datasets/nnue2/probe/<NAME>.{pt,json,log}
"""
from __future__ import annotations

import os

os.environ.setdefault("OMP_NUM_THREADS", "2")
os.environ.setdefault("MKL_NUM_THREADS", "2")

import argparse  # noqa: E402
import json  # noqa: E402
import math  # noqa: E402
import sys  # noqa: E402
import time  # noqa: E402
from pathlib import Path  # noqa: E402

import numpy as np  # noqa: E402
import torch  # noqa: E402
import torch.nn.functional as F  # noqa: E402
from torch import nn  # noqa: E402

sys.path.insert(0, str(Path(__file__).resolve().parent))
import probe  # noqa: E402
from probe import N_PAT, OUT, POW3  # noqa: E402

import eval_data  # noqa: E402  (probe put tools/ on sys.path)

CJK_BITS = 14  # payload units: one CodinGame unit carries 14 bits (CJK14, documentation/minification.md)
DIGITS = np.array([(p // POW3) % 3 for p in range(N_PAT)])  # (3^9, 9): value of square i in pattern p


def onehot_table():
    """(3^9, 27): row p has a 1 at 3*i + value_i(p) for each square i (0 empty, 1 mine, 2 theirs)."""
    t = np.zeros((N_PAT, 27), np.float32)
    t[np.arange(N_PAT)[:, None], 3 * np.arange(9)[None, :] + DIGITS] = 1.0
    return t


# ---------------------------------------------------------------- logging
class Log:
    def __init__(self):
        self.f = None

    def to(self, path):
        if self.f:
            self.f.close()
        self.f = open(path, "a", encoding="utf-8") if path else None

    def __call__(self, msg):
        line = f"[{time.strftime('%H:%M:%S')}] {msg}"
        print(line, flush=True)
        if self.f:
            self.f.write(line + "\n")
            self.f.flush()


log = Log()


# ---------------------------------------------------------------- model
class Gen(nn.Module):
    def __init__(self, fx, A=128, dense=(16, 32), enc=(64, 64, 32), forced=True, row_std=0.05, shared_con=False):
        super().__init__()
        self.fx, self.A, self.forced, self.shared_con = fx, A, forced, shared_con
        dev = fx.dev
        self.register_buffer("onehot", torch.from_numpy(onehot_table()), persistent=False)
        self.register_buffer("ar3", torch.tensor([1, 2, 3]), persistent=False)
        self.register_buffer("ar10u8", torch.arange(10, dtype=torch.uint8), persistent=False)
        layers, d = [], 27
        for i, w in enumerate(enc):
            layers.append(nn.Linear(d, w))
            if i < len(enc) - 1:
                layers.append(nn.ReLU())
            d = w
        self.enc = nn.Sequential(*layers)
        E, W = enc[-1], A + 1
        self.E = E
        self.proj_w = nn.Parameter(torch.randn(9, E, W))
        self.proj_b = nn.Parameter(torch.zeros(9, W))
        self.dec = nn.Parameter(row_std * torch.randn(27, W))  # 3*m + (state - 1): mine, theirs, drawn
        # [c] side to move's view, [10 + c] the other's (shared_con: one set of 10 for both, as probe.Pat)
        self.con = nn.Parameter(row_std * torch.randn(10 if shared_con else 20, W))
        if forced:
            self.fwd_w = nn.Parameter(torch.randn(E, W))
            self.fwd_b = nn.Parameter(torch.zeros(W))
        self.bias = nn.Parameter(torch.cat([torch.full((A,), 0.5), torch.zeros(1)]))
        dims = [2 * A, *dense, 1]
        self.dense = nn.ModuleList(nn.Linear(a, b) for a, b in zip(dims[:-1], dims[1:]))
        with torch.no_grad():  # a generated row starts with std ~row_std, like the free-table rows
            h = self.enc(self.onehot)
            self.proj_w.mul_(row_std / float(torch.einsum("pk,lkj->lpj", h, self.proj_w).std()))
            if forced:
                self.fwd_w.mul_(row_std / float((h @ self.fwd_w).std()))
        self.to(dev)

    def first_layer(self):
        """Stacked first-layer rows in the order of features()."""
        parts = [self.proj_w.reshape(-1, self.A + 1), self.proj_b, self.dec, self.con]
        if self.forced:
            parts += [self.fwd_w, self.fwd_b[None]]
        return torch.cat(parts, 0)

    def table(self):
        """(9, 3^9, A+1): the generated pattern rows T[m, p] the engine would build at startup."""
        h = self.enc(self.onehot)
        return torch.einsum("pk,lkj->lpj", h, self.proj_w) + self.proj_b[:, None, :]

    def features(self, h, pat, sup, con, side):
        b = pat.shape[0]
        live = sup == 0
        hb = F.embedding(pat, h) * live[..., None].float()  # (b, 9, E): generated rows only for live boards
        dec = (sup[:, :, None] == self.ar3[None, None, :]).float().reshape(b, 27)
        c = (con[:, None] == self.fx.ar10[None, :]).float()
        z = torch.zeros_like(c)
        cc = c if self.shared_con else torch.cat([c, z] if side == 0 else [z, c], 1)
        parts = [hb.reshape(b, -1), live.float(), dec, cc]
        if self.forced:
            forced = con < 9
            pf = torch.gather(pat, 1, torch.clamp(con, max=8)[:, None]).squeeze(1)
            parts += [F.embedding(pf, h) * forced[:, None].float(), forced[:, None].float()]
        return torch.cat(parts, 1)

    def accumulators(self, cells, sup, con):
        """Pre-activation (b, A+1) accumulators of the side to move and of the opponent."""
        b = cells.shape[0]
        pat = (cells.reshape(b, 9, 9) * self.fx.pow3).sum(2)  # probe.Pat's index: sum_i cell_i 3^i
        pat_n = self.fx.pat_swap[pat]  # the opponent's view: mine <-> theirs
        sup_n = self.fx.sup_swap[sup]
        h = self.enc(self.onehot)
        f = torch.cat([self.features(h, pat, sup, con, 0), self.features(h, pat_n, sup_n, con, 1)], 0)
        acc = f @ self.first_layer() + self.bias
        return acc[:b], acc[b:]

    def accumulators_fast(self, xb):
        """Same accumulators from a (b, 91) uint8 compact batch without pattern indices: every board's
        27-slot one-hot (3*square + value; the opponent's view swaps the mine/theirs slots) goes through
        the encoder directly. Few, dense ops and no embedding backward, which DirectML runs slowly;
        `check` verifies it equals accumulators() and the free-table Pat indexing."""
        b = xb.shape[0]
        cells, sup, con = xb[:, :81], xb[:, 81:90], xb[:, 90:91]
        e0, e1, e2 = (cells == 0).float(), (cells == 1).float(), (cells == 2).float()
        oh = torch.cat([torch.stack([e0, e1, e2], 2), torch.stack([e0, e2, e1], 2)], 0).reshape(2 * b, 9, 27)
        h = self.enc(oh)  # (2b, 9, E)
        s1, s2, s3 = (sup == 1).float(), (sup == 2).float(), (sup == 3).float()
        live = (sup == 0).float()
        live2 = torch.cat([live, live], 0)
        dec = torch.cat([torch.stack([s1, s2, s3], 2), torch.stack([s2, s1, s3], 2)], 0).reshape(2 * b, 27)
        c = (con == self.ar10u8).float()  # (b, 10)
        z = torch.zeros_like(c)
        cc = torch.cat([c, c], 0) if self.shared_con else torch.cat([torch.cat([c, z], 1), torch.cat([z, c], 1)], 0)
        parts = [(h * live2[..., None]).reshape(2 * b, -1), live2, dec, cc]
        if self.forced:
            fo = torch.cat([c[:, :9], c[:, :9]], 0)  # one-hot of the forced board (all zero on a free move)
            parts += [(h * fo[..., None]).sum(1), fo.sum(1, keepdim=True)]
        acc = torch.cat(parts, 1) @ self.first_layer() + self.bias
        return acc[:b], acc[b:]

    def fast(self, xb, with_psqt=False):
        e, ps = self.head(*self.accumulators_fast(xb))
        return (e, ps) if with_psqt else e

    def head(self, us, them):
        x = torch.clamp(torch.cat([us[:, :self.A], them[:, :self.A]], 1), 0, 1)
        for i, lin in enumerate(self.dense):
            x = lin(x)
            if i < len(self.dense) - 1:
                x = torch.clamp(x, 0, 1)
        psqt = 0.5 * (us[:, self.A] - them[:, self.A])
        return (x.squeeze(1) + psqt) * 1000.0, psqt * 1000.0

    def forward(self, cells, sup, con, with_psqt=False):
        e, ps = self.head(*self.accumulators(cells, sup, con))
        return (e, ps) if with_psqt else e


def n_params(m):
    return int(sum(p.numel() for p in m.parameters()))


def payload(params):
    return {f"{b}bit": int(math.ceil(params * b / CJK_BITS)) for b in (7, 8)}


def parse_run(s):
    """NAME,A,DENSE,LR[,forced=0|1][,sharedcon=0|1][,seed=N][,epochs=N]"""
    name, A, dense, lr, *opts = s.split(",")
    r = dict(name=name, A=int(A), dense=tuple(int(v) for v in dense.split("x")), lr=float(lr))
    for o in opts:
        k, v = o.split("=")
        r[k] = int(v)
    return r


def build(fx, a):
    """Model from a saved run's args (json 'args')."""
    return Gen(fx, a["A"], tuple(a["dense"]), tuple(a.get("enc", (64, 64, 32))), a.get("forced", True),
               shared_con=a.get("shared_con", False))


# ---------------------------------------------------------------- unit check
def sample_rows(n_per_file=20000):
    xs = []
    for p in probe.DATA:
        r = np.array(eval_data.load(str(p))[: n_per_file * 3])
        r = r[(r["flags"] & eval_data.F_SEARCH) != 0][:n_per_file]
        xs.append(probe.compact(r))
    return np.concatenate(xs)


def direct_acc(m, cells, sup, con):
    """Accumulators from the cells directly (per-board one-hot -> encoder), no pattern indices."""
    b = cells.shape[0]
    out = []
    for side in (0, 1):
        cv = cells if side == 0 else torch.where(cells == 0, cells, 3 - cells)
        sv = sup if side == 0 else torch.where((sup == 1) | (sup == 2), 3 - sup, sup)
        h = m.enc(F.one_hot(cv.reshape(b, 9, 9), 3).float().reshape(b, 9, 27))  # slot 3*square + value
        acc = m.bias.expand(b, -1).clone()
        for loc in range(9):
            row = h[:, loc] @ m.proj_w[loc] + m.proj_b[loc]
            dec = m.dec[3 * loc + (sv[:, loc] - 1).clamp(min=0)]
            acc = acc + torch.where((sv[:, loc] == 0)[:, None], row, dec)
        acc = acc + m.con[con + 10 * side]
        if m.forced:
            hf = h[torch.arange(b), con.clamp(max=8)]
            acc = acc + torch.where((con < 9)[:, None], hf @ m.fwd_w + m.fwd_b, torch.zeros_like(acc))
        out.append(acc)
    return out


def d4_pattern_perm():
    """PP[g][p]: the 3^9 index of pattern p after symmetry g (square i moves to probe.P9[g][i])."""
    PP = np.zeros((8, N_PAT), np.int64)
    for g in range(8):
        nd = np.zeros_like(DIGITS)
        nd[:, probe.P9[g]] = DIGITS
        PP[g] = (nd * POW3).sum(1)
    return PP


def check_d4_encoding(fx, xc, A):
    """Review checks on compact rows xc (n, 91), CPU.
    - pattern level: pat(T_g x)[:, P9[g][m]] == PP[g][pat(x)[:, m]] on live boards, and PP[g] commutes
      with the mine/theirs swap (so the opponent's view transforms the same way);
    - encoder-input level: Gen.features() fed the one-hot table (the 27 generator inputs per board plus
      live / decided / constraint / forced rows) of the transformed row equals the original row's
      features pushed through the symmetry's input permutation, for both perspectives;
    - colour flip: swapping mine/theirs (cells and decided boards) turns the side-to-move accumulator
      into the opponent's, up to the per-perspective constraint row, on accumulators_fast."""
    out = {}
    PP = d4_pattern_perm()
    X = torch.from_numpy(xc)
    cells, sup, con = fx.split(X)
    n = len(xc)
    pat = (cells.reshape(n, 9, 9) * fx.pow3).sum(2).numpy()
    swp = fx.pat_swap.numpy()
    out["d4_swap_commute_mismatches"] = int(sum((swp[PP[g]] != PP[g][swp]).sum() for g in range(8)))
    m = Gen(fx, A=A, forced=True)
    oh = torch.from_numpy(onehot_table())
    # feature layout of Gen.features: 9 x 27 generated inputs | 9 live | 27 decided | 20 constraint | 27 forced | 1
    P9 = probe.P9
    pat_bad = feat_bad = 0
    for g in range(8):
        xt = xc[:, COLPERM[g]]
        xt[:, 90] = probe.CONMAP[g][xc[:, 90]]
        ct, st, kt = fx.split(torch.from_numpy(xt))
        pt = (ct.reshape(n, 9, 9) * fx.pow3).sum(2).numpy()
        live = sup.numpy() == 0
        for mb in range(9):
            pat_bad += int((pt[:, P9[g][mb]][live[:, mb]] != PP[g][pat[:, mb]][live[:, mb]]).sum())
        perm = np.arange(9 * 27 + 9 + 27 + 20 + 28)  # new feature j reads old feature perm[j]
        for mb in range(9):
            for i in range(9):
                for v in range(3):
                    perm[27 * P9[g][mb] + 3 * P9[g][i] + v] = 27 * mb + 3 * i + v
            perm[243 + P9[g][mb]] = 243 + mb
            for j in range(3):
                perm[252 + 3 * P9[g][mb] + j] = 252 + 3 * mb + j
        for blk in (279, 289):
            for c in range(10):
                perm[blk + probe.CONMAP[g][c]] = blk + c
        for i in range(9):
            for v in range(3):
                perm[299 + 3 * P9[g][i] + v] = 299 + 3 * i + v
        with torch.no_grad():
            for side in (0, 1):
                p0 = torch.from_numpy(pat) if side == 0 else fx.pat_swap[torch.from_numpy(pat)]
                s0 = sup if side == 0 else fx.sup_swap[sup]
                p1 = torch.from_numpy(pt) if side == 0 else fx.pat_swap[torch.from_numpy(pt)]
                s1 = st if side == 0 else fx.sup_swap[st]
                f0 = m.features(oh, p0, s0, con, side)
                f1 = m.features(oh, p1, s1, kt, side)
                feat_bad += int((f1 != f0[:, perm]).any(1).sum())
    out["d4_pattern_index_mismatches"] = pat_bad
    out["d4_encoder_input_mismatches"] = feat_bad
    with torch.no_grad():
        for p in m.parameters():
            p.add_(0.1 * torch.randn_like(p))
        xf = xc.copy()
        xf[:, :90] = np.where((xc[:, :90] == 1) | (xc[:, :90] == 2), 3 - xc[:, :90], xc[:, :90])
        us, them = m.accumulators_fast(torch.from_numpy(xc))
        fus, fthem = m.accumulators_fast(torch.from_numpy(xf))
        k = torch.from_numpy(xc[:, 90].astype(np.int64))
        d1 = (fus - m.con[k]) - (them - m.con[10 + k])
        d2 = (fthem - m.con[10 + k]) - (us - m.con[k])
        out["colour_flip_max_abs"] = float(max(d1.abs().max(), d2.abs().max()))
    return out


def cmd_check(args):
    torch.manual_seed(0)
    torch.set_num_threads(2)
    res = {}
    oh = onehot_table()
    # 1. one-hot table rows decode back to their own index, in probe's POW3 order
    back = (oh.reshape(N_PAT, 9, 3).argmax(2) * POW3).sum(1)
    res["onehot_decodes_to_index"] = bool((back == np.arange(N_PAT)).all() and (oh.sum(1) == 9).all())
    fx = probe.Feats(torch.device("cpu"))
    x = sample_rows(args.n)
    X = torch.from_numpy(x)
    cells, sup, con = fx.split(X)
    variants = [("identity", (cells, sup, con))]
    torch.manual_seed(1)
    variants.append(("random D4", fx.augment(cells, sup, con)))
    # 1b. the training-time compact-row transform (augment_np's COLPERM / CONMAP) equals compacting the
    #     transformed 93-char states (probe.transform_states, verified against the HCE), for all 8 symmetries
    r = np.array(eval_data.load(str(probe.DATA[0]))[:30000])
    r = r[(r["flags"] & eval_data.F_SEARCH) != 0]
    st = np.frombuffer(r["s"].tobytes(), dtype=np.uint8).reshape(-1, 93)
    xc = probe.compact(r)
    mism = 0
    for gsym in range(8):
        t = r.copy()
        t["s"] = np.frombuffer(probe.transform_states(st, np.full(len(st), gsym)).tobytes(), dtype="S93")
        mine = xc[:, COLPERM[gsym]]
        mine[:, 90] = probe.CONMAP[gsym][xc[:, 90]]
        mism += int((mine != probe.compact(t)).any(1).sum())
    xa = augment_np(xc)  # the stratified batch version applies one of those 8 maps to each row
    ok_rows = np.zeros(len(xc), bool)
    for gsym in range(8):
        mine = xc[:, COLPERM[gsym]]
        mine[:, 90] = probe.CONMAP[gsym][xc[:, 90]]
        ok_rows |= (mine == xa).all(1)
    res["compact_transform_mismatches"] = mism
    res["augment_np_rows_not_a_symmetry"] = int((~ok_rows).sum())
    # 1c. (review) transform-then-encode == encode-then-transform on B's own inputs, all 8 symmetries,
    #     both perspectives; and a mine/theirs colour flip moves the side-to-move accumulator onto the
    #     opponent's (up to the per-perspective constraint row) through the training path
    res.update(check_d4_encoding(probe.Feats(torch.device("cpu")), xc, args.A))
    # 2. forced boards are always live (the forced-board row reads a live pattern)
    f = con < 9
    res["forced_board_live"] = bool((torch.gather(sup, 1, con.clamp(max=8)[:, None]).squeeze(1)[f] == 0).all())
    res["rows"] = int(len(x))
    res["forced_frac"] = float(f.float().mean())
    worst_direct, worst_pat, worst_swap = 0.0, 0.0, 0.0
    with torch.no_grad():
        for vname, (c, s, k) in variants:
            # 3. generated rows through pattern indices == generated rows from the cells directly
            m = Gen(fx, A=args.A, forced=True)
            for p in m.parameters():  # random, non-trivial values everywhere
                p.add_(0.1 * torch.randn_like(p))
            us, them = m.accumulators(c, s, k)
            dus, dthem = direct_acc(m, c, s, k)
            worst_direct = max(worst_direct, float((us - dus).abs().max()), float((them - dthem).abs().max()))
            xb = torch.cat([c, s, k[:, None]], 1).to(torch.uint8)
            fus, fthem = m.accumulators_fast(xb)
            worst_direct = max(worst_direct, float((us - fus).abs().max()), float((them - fthem).abs().max()))
            res[f"{vname}: max|index path - fast path| eval"] = float((m.head(us, them)[0] - m.fast(xb)).abs().max())
            # 4. against probe.Pat: load the materialized table into a free-table Pat and let Pat's own
            #    forward compute the pattern indices (sum cell*3^i, decided -> 0, pat_swap for the opponent)
            m2 = Gen(fx, A=args.A, forced=False)
            for p in m2.parameters():
                p.add_(0.1 * torch.randn_like(p))
            m2.con[10:] = m2.con[:10]  # Pat shares one constraint row between perspectives
            T = m2.table()  # (9, 3^9, A+1)
            pat_m = probe.Pat(fx, width=args.A + 1)
            pat_m.ft.copy_(T.reshape(9 * N_PAT, args.A + 1))
            fs = torch.zeros(36, args.A + 1)
            for loc in range(9):  # Pat adds FT[m, empty] + FS[m, state] on a decided board
                for st in (1, 2, 3):
                    fs[4 * loc + st] = m2.dec[3 * loc + st - 1] - T[loc, 0]
            pat_m.fs.copy_(fs)
            pat_m.fc.copy_(m2.con[:10])
            pat_m.fb.copy_(m2.bias)
            got = []
            orig = pat_m.acc
            pat_m.acc = lambda *a: got.append(a) or orig(*a)  # noqa: E731
            pat_m(c, s, k)
            pu = F.embedding(pat_m.fx.loc * N_PAT + got[0][0], pat_m.ft).sum(1) \
                + F.embedding(pat_m.fx.loc * 4 + got[0][1], pat_m.fs).sum(1) + F.embedding(got[0][2], pat_m.fc) + pat_m.fb
            pn = F.embedding(pat_m.fx.loc * N_PAT + got[1][0], pat_m.ft).sum(1) \
                + F.embedding(pat_m.fx.loc * 4 + got[1][1], pat_m.fs).sum(1) + F.embedding(got[1][2], pat_m.fc) + pat_m.fb
            gu, gt = m2.accumulators(c, s, k)
            worst_pat = max(worst_pat, float((pu - gu).abs().max()), float((pn - gt).abs().max()))
            # and Pat's clipped accumulators (its own acc()) agree too
            worst_pat = max(worst_pat, float((orig(*got[0]) - gu.clamp(0, 1)).abs().max()))
            # 5. the opponent's pattern index equals the index of the colour-swapped cells
            b = c.shape[0]
            sw = torch.where(c == 0, c, 3 - c)
            p_sw = (sw.reshape(b, 9, 9) * fx.pow3).sum(2)
            p_ix = fx.pat_swap[(c.reshape(b, 9, 9) * fx.pow3).sum(2)]
            worst_swap = max(worst_swap, float((p_sw != p_ix).float().sum()))
            res[f"{vname}: max|gen - direct|"] = float(max((us - dus).abs().max(), (them - dthem).abs().max()))
    res["max_abs_gen_vs_direct"] = worst_direct
    res["max_abs_gen_vs_pat_free_table"] = worst_pat
    res["swap_index_mismatches"] = worst_swap
    ok = res["onehot_decodes_to_index"] and res["forced_board_live"] and worst_direct < 1e-4 and worst_pat < 1e-4 \
        and worst_swap == 0 and mism == 0 and res["augment_np_rows_not_a_symmetry"] == 0 \
        and res["d4_pattern_index_mismatches"] == 0 and res["d4_swap_commute_mismatches"] == 0 \
        and res["d4_encoder_input_mismatches"] == 0 and res["colour_flip_max_abs"] < 1e-4
    res["PASS"] = bool(ok)
    (OUT / "gen_check.json").write_text(json.dumps(res, indent=1))
    print(json.dumps(res, indent=1))
    if not ok:
        sys.exit(1)


# ---------------------------------------------------------------- throughput bench
def get_dev(name):
    if name == "dml":
        import torch_directml
        return torch_directml.device()
    return torch.device(name)


# gather form on the 91-column compact row: new[:, j] = old[:, COLPERM[g][j]] (cells, board states; the
# constraint column is remapped through probe.CONMAP). Same maps as probe.Feats.augment / transform_states.
COLPERM = np.concatenate([probe.G81, 81 + probe.G9, np.full((8, 1), 90)], 1)


def augment_np(xb):
    """Random D4 symmetry per row, stratified: the batch rows come in a fresh random order every epoch,
    so giving slice j of the batch symmetry (j + shift) % 8 gives every row a uniformly random symmetry.
    Done on the CPU with fixed column permutations: DirectML's batched gathers are slow."""
    n = len(xb)
    shift = np.random.randint(8)
    out = np.empty_like(xb)
    for j in range(8):
        sl = slice(j * n // 8, (j + 1) * n // 8)
        g = (j + shift) % 8
        out[sl] = xb[sl][:, COLPERM[g]]
        out[sl, 90] = probe.CONMAP[g][xb[sl, 90]]
    return out


class AdamW:
    """AdamW with decoupled weight decay from ops DirectML runs natively (torch's Adam falls back to the
    CPU for lerp); per-group weight decay, lr set by the caller every step."""

    def __init__(self, groups, betas=(0.9, 0.999), eps=1e-8):
        self.groups = [(list(g["params"]), g["weight_decay"]) for g in groups]
        self.b1, self.b2, self.eps, self.t = betas[0], betas[1], eps, 0
        self.state = {id(p): (torch.zeros_like(p), torch.zeros_like(p)) for ps, _ in self.groups for p in ps}

    @torch.no_grad()
    def step(self, lr):
        self.t += 1
        b1, b2 = self.b1, self.b2
        bc1, bc2 = 1 - b1 ** self.t, 1 - b2 ** self.t
        for ps, wd in self.groups:
            for p in ps:
                if p.grad is None:
                    continue
                m, v = self.state[id(p)]
                m.mul_(b1).add_(p.grad, alpha=1 - b1)
                v.mul_(b2).addcmul_(p.grad, p.grad, value=1 - b2)
                if wd:
                    p.mul_(1 - lr * wd)
                p.addcdiv_(m, (v / bc2).sqrt_().add_(self.eps), value=-lr / bc1)


def cmd_bench(args):
    probe.below_normal_priority()
    torch.set_num_threads(2)
    dev = get_dev(args.device)
    fx = probe.Feats(dev)
    x = sample_rows(40000)
    y = torch.rand(len(x))
    for spec in args.run:
        r = parse_run(spec)
        m = Gen(fx, r["A"], r["dense"])
        opt = AdamW([dict(params=m.parameters(), weight_decay=0.0)])
        for it in range(args.steps + 3):
            if it == 3:
                torch.zeros(1, device=dev).sum().item()
                t0 = time.time()
            idx = np.random.randint(0, len(x), args.batch)
            xb = torch.from_numpy(augment_np(x[idx])).to(dev)
            e, ps = m.fast(xb, with_psqt=True)
            yy = y[idx].to(dev)
            loss = (torch.sigmoid(e / 1600) - yy).pow(2).mean() + 0.1 * (torch.sigmoid(ps / 1600) - yy).pow(2).mean()
            for q in m.parameters():
                q.grad = None
            loss.backward()
            torch.nn.utils.clip_grad_norm_(m.parameters(), 1.0, foreach=False)
            opt.step(1e-3)
        loss.item()
        dt = (time.time() - t0) / args.steps
        print(f"{r['name']}: {n_params(m):,} params, {args.batch / dt:,.0f} rows/s ({1000 * dt:.1f} ms/step)", flush=True)


# ---------------------------------------------------------------- training
def load_train_data(extra, extra_rows, max_rows=0):
    """probe.cmd_train's data path: eval2 (+ holdout) and the first extra_rows records of `extra` as training."""
    x, search, static, hce, hold, game = probe.load_data(max_rows, 1)
    n_extra = 0
    if extra:
        mm = np.memmap(probe.repo_path(extra), dtype=eval_data.REC, mode="r", shape=(extra_rows,))
        n0, cap = len(x), len(x) + extra_rows
        grow = lambda a: np.concatenate([a, np.zeros((cap - n0,) + a.shape[1:], dtype=a.dtype)])  # noqa: E731
        x, search, static, hce, game = grow(x), grow(search), grow(static), grow(hce), grow(game)
        for i in range(0, extra_rows, 2_000_000):
            er = np.array(mm[i:i + 2_000_000])
            er = er[(er["flags"] & eval_data.F_SEARCH) != 0]
            sl = slice(n0 + n_extra, n0 + n_extra + len(er))
            x[sl] = probe.compact(er)
            search[sl] = er["search"]
            static[sl] = er["static_eval"]
            hce[sl] = er["hce"]
            game[sl] = er["game"].astype(np.int64) + (2 << 32)
            n_extra += len(er)
            del er
        del mm
        x, search, static, hce, game = (a[:n0 + n_extra] for a in (x, search, static, hce, game))
        hold = np.concatenate([hold, np.zeros(n_extra, dtype=bool)])
    return x, search, static, hce, hold, game, n_extra


def lr_lambda(total, warm_frac, floor):
    warm = max(1, int(warm_frac * total))

    def f(s):
        if s < warm:
            return (s + 1) / warm
        t = min(1.0, (s - warm) / max(1, total - warm))
        return floor + (1 - floor) * 0.5 * (1 + math.cos(math.pi * t))
    return f


def train_one(r, args, data, dev, fx):
    name = r["name"]
    log.to(OUT / f"{name}.log")
    x, search, static, hce, hold, n_extra, load_msg = data
    k = args.k
    seed = r.get("seed", args.seed)
    forced = bool(r.get("forced", not args.no_forced))
    shared_con = bool(r.get("sharedcon", 0))
    epochs = r.get("epochs", args.epochs)
    aug = bool(r.get("aug", 1))
    d1 = bool(r.get("static", 0))  # D1 capacity fit: the target is the shipped static eval, not the search
    torch.manual_seed(seed)
    np.random.seed(seed)
    rng = np.random.default_rng(seed)
    for line in load_msg:
        log(line)
    tr = np.flatnonzero(~hold)
    va = np.flatnonzero(hold)
    X = torch.from_numpy(x)
    tgt = static if d1 else search
    Y = torch.from_numpy((1 / (1 + np.exp(-tgt / k))).astype(np.float32))
    model = Gen(fx, r["A"], r["dense"], tuple(args.enc), forced, args.row_std, shared_con)
    params = n_params(model)
    log(f"{name}: B generator, A {r['A']}, dense {2 * r['A']}->{'->'.join(map(str, r['dense']))}->1, enc 27->"
        f"{'->'.join(map(str, args.enc))}, forced row {forced}, shared constraint rows {shared_con}, seed {seed};"
        f" {params:,} params; payload "
        f"{payload(params)} units; AdamW lr {r['lr']} cosine (warmup {args.warmup:.0%}, floor {args.lr_floor}),"
        f" batch {args.batch}, {epochs} epochs, psqt aux {args.psqt_w}, aug {aug}"
        + ("; D1: target = shipped static_eval" if d1 else ""))
    vx = X[va]
    yv = Y[va].numpy().astype(np.float64)
    sv = tgt[va]
    ship_loss = float(((1 / (1 + np.exp(-static[va] / k)) - yv) ** 2).mean()) or float("nan")  # nan in D1 mode
    log(f"train {len(tr):,} rows ({n_extra:,} extra), holdout {len(va):,}; shipped static_eval loss {ship_loss:.6f}")

    def predict(xs, want_acc=False):
        model.eval()
        out, dead = [], None
        with torch.no_grad():
            for i in range(0, len(xs), 65536):
                us, them = model.accumulators_fast(xs[i:i + 65536].to(dev))
                e, ps = model.head(us, them)
                out.append(torch.stack([e, ps], 1).cpu())
                if want_acc and i == 0:  # clipped-ReLU health on the first 65k holdout rows
                    a = torch.cat([us[:, :model.A], them[:, :model.A]], 0)
                    dead = dict(dead=float(((a <= 0).all(0)).float().mean()),
                                saturated=float(((a >= 1).all(0)).float().mean()),
                                active_frac=float(((a > 0) & (a < 1)).float().mean()))
        model.train()
        o = torch.cat(out).numpy().astype(np.float64)
        return o[:, 0], o[:, 1], dead

    def stats(e, ps):
        p = 1 / (1 + np.exp(-e / k))
        nm = np.abs(sv) < 8000
        return dict(val=float(((p - yv) ** 2).mean()),
                    val_psqt=float(((1 / (1 + np.exp(-ps / k)) - yv) ** 2).mean()),
                    std=float(e.std()), mae=float(np.abs(e - sv).clip(max=20000).mean()),
                    corr_search=float(np.corrcoef(e[nm], sv[nm])[0, 1]),
                    corr_static=float(np.corrcoef(e, static[va])[0, 1]),
                    r2_target=float(1 - ((e - sv) ** 2).mean() / sv.var()))

    first = [p for n, p in model.named_parameters() if not n.startswith("dense.")]
    dense = [p for n, p in model.named_parameters() if n.startswith("dense.")]
    opt = AdamW([dict(params=first, weight_decay=0.0), dict(params=dense, weight_decay=args.wd)], betas=(0.9, 0.999))
    n_steps = len(tr) // args.batch
    steps = max(1, epochs * n_steps)
    lr_at = lr_lambda(steps, args.warmup, args.lr_floor / r["lr"])
    best, hist = None, []
    t_start = time.time()
    train_secs, rows_done = 0.0, 0
    for epoch in range(1, epochs + 1):
        t0 = time.time()
        ep_train_secs = 0.0
        perm = rng.permutation(tr)
        run = torch.zeros(2, device=dev)  # summed on the device: no per-step sync
        seen = 0
        ts = time.time()
        for step in range(n_steps):
            if step and step % max(1, n_steps // 4) == 0:
                rl = run.cpu().numpy() / seen
                dt = time.time() - ts
                train_secs += dt
                ep_train_secs += dt
                done = (epoch - 1) * n_steps + step
                el = time.time() - t_start
                eta = el / done * (steps - done)
                log(f"{name} epoch {epoch} step {step}/{n_steps} train {rl[0]:.6f} psqt {rl[1]:.6f}"
                    f" lr {r['lr'] * lr_at(done):.2e} {(rows_done + seen) / max(1e-9, train_secs):,.0f} rows/s"
                    f" elapsed {el / 60:.1f}m eta {eta / 60:.1f}m")
                ts = time.time()
            idx = perm[step * args.batch:(step + 1) * args.batch]
            xb = torch.from_numpy(augment_np(x[idx]) if aug else x[idx]).to(dev)
            y = Y[idx].to(dev)
            e, ps = model.fast(xb, with_psqt=True)
            l_main = (torch.sigmoid(e / k) - y).pow(2).mean()
            l_ps = (torch.sigmoid(ps / k) - y).pow(2).mean()
            loss = l_main + args.psqt_w * l_ps
            for q in model.parameters():
                q.grad = None
            loss.backward()
            torch.nn.utils.clip_grad_norm_(model.parameters(), args.clip, foreach=False)
            opt.step(r["lr"] * lr_at((epoch - 1) * n_steps + step))
            run += torch.stack([l_main.detach(), l_ps.detach()]) * len(idx)
            seen += len(idx)
        rl = run.cpu().numpy() / max(1, seen)
        dt = time.time() - ts
        train_secs += dt
        ep_train_secs += dt
        rows_done += seen
        e_v, ps_v, health = predict(vx, want_acc=True)
        st = stats(e_v, ps_v)
        st.update(epoch=epoch, train=float(rl[0]), train_psqt=float(rl[1]),
                  secs=time.time() - t0, rows_per_s=seen / max(1e-9, ep_train_secs), **(health or {}))
        hist.append(st)
        log(f"{name} epoch {epoch}: train {st['train']:.6f} val {st['val']:.6f} ({100 * (st['val'] / ship_loss - 1):+.2f}%"
            f" vs shipped) psqt-only val {st['val_psqt']:.6f} std {st['std']:.0f} corr(search) {st['corr_search']:.3f}"
            f" corr(static) {st['corr_static']:.3f} R2(target) {st['r2_target']:.4f}; acc lanes dead {st.get('dead', 0):.1%} saturated"
            f" {st.get('saturated', 0):.1%}; {st['rows_per_s']:,.0f} rows/s ({st['secs']:.0f}s)")
        if not math.isfinite(st["val"]):
            break
        if best is None or st["val"] < best["val"]:
            best = st
            torch.save({n: p.detach().cpu() for n, p in model.state_dict().items()}, OUT / f"{name}.pt")
    a = dict(arm="gen", A=r["A"], dense=list(r["dense"]), lr=r["lr"], enc=list(args.enc), forced=forced, shared_con=shared_con,
             batch=args.batch, epochs=epochs, k=k, psqt_w=args.psqt_w, wd_dense=args.wd, clip=args.clip,
             warmup=args.warmup, lr_floor=args.lr_floor, row_std=args.row_std, aug=aug, target="static" if d1 else "search", seed=seed,
             extra=args.extra, extra_rows=args.extra_rows)
    summary = dict(name=name, arm="gen", aug=aug, best=best, hist=hist, params=params, payload_units=payload(params),
                   train_rows=int(len(tr)), extra_rows=int(n_extra), holdout_rows=int(len(va)), steps=steps,
                   shipped_loss=ship_loss, vs_shipped_pct=100 * (best["val"] / ship_loss - 1),
                   rows_per_s=rows_done / max(1e-9, train_secs), train_minutes=(time.time() - t_start) / 60,
                   args=a)
    (OUT / f"{name}.json").write_text(json.dumps(summary, indent=1))
    log(f"RESULT {name}: best val {best['val']:.6f} (epoch {best['epoch']}), {summary['vs_shipped_pct']:+.2f}% vs shipped"
        f" {ship_loss:.6f}; std {best['std']:.0f}; {params:,} params; {summary['rows_per_s']:,.0f} rows/s;"
        f" train {summary['train_minutes']:.1f} min")
    log.to(None)


def cmd_train(args):
    probe.below_normal_priority()
    torch.set_num_threads(args.threads)
    OUT.mkdir(parents=True, exist_ok=True)
    runs = [parse_run(s) for s in args.run]
    t0 = time.time()
    x, search, static, hce, hold, game, n_extra = load_train_data(args.extra, args.extra_rows, args.max_rows)
    msg = [f"data: {len(x):,} rows ({n_extra:,} labeled extra rows from the first {args.extra_rows:,} records of"
           f" {args.extra}); loaded in {time.time() - t0:.0f}s"]
    print(msg[0], flush=True)
    del game
    dev = get_dev(args.device)
    fx = probe.Feats(dev)
    for r in runs:
        train_one(r, args, (x, search, static, hce, hold, n_extra, msg), dev, fx)


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("check")
    p.add_argument("--n", type=int, default=20000)
    p.add_argument("--A", type=int, default=32)
    p.set_defaults(fn=cmd_check)
    p = sub.add_parser("bench")
    p.add_argument("--run", action="append", required=True)
    p.add_argument("--batch", type=int, default=16384)
    p.add_argument("--steps", type=int, default=20)
    p.add_argument("--device", default="dml")
    p.set_defaults(fn=cmd_bench)
    p = sub.add_parser("train")
    p.add_argument("--run", action="append", required=True, help="NAME,A,DENSE,LR e.g. B128,128,16x32,1e-3")
    p.add_argument("--k", type=float, default=1600.0)
    p.add_argument("--epochs", type=int, default=10)
    p.add_argument("--batch", type=int, default=16384)
    p.add_argument("--enc", type=int, nargs="+", default=[64, 64, 32])
    p.add_argument("--no-forced", action="store_true")
    p.add_argument("--psqt-w", type=float, default=0.1)
    p.add_argument("--wd", type=float, default=1e-5, help="AdamW weight decay on the dense layers (0 on the first)")
    p.add_argument("--clip", type=float, default=1.0)
    p.add_argument("--warmup", type=float, default=0.02)
    p.add_argument("--lr-floor", type=float, default=1e-5)
    p.add_argument("--row-std", type=float, default=0.05)
    p.add_argument("--extra", default="datasets/nnue2/d8_a.cfdg")
    p.add_argument("--extra-rows", type=int, default=5_000_000)
    p.add_argument("--max-rows", type=int, default=0, help="smoke tests: random subset of the eval2 rows")
    p.add_argument("--device", default="dml")
    p.add_argument("--threads", type=int, default=2)
    p.add_argument("--seed", type=int, default=1)
    p.set_defaults(fn=cmd_train)
    args = ap.parse_args()
    args.fn(args)


if __name__ == "__main__":
    main()
